import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, Hash, ListFilter, CalendarDays, Archive } from 'lucide-react';
import MarketDashboard from './components/MarketDashboard';
import { generateMarketSummary } from './services/geminiService';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiSummary, setAiSummary] = useState('');

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth]);

  // 更新逻辑：只有“进行中”被视为活跃
  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: data.updatedAt || i.updatedAt } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        return { ...i, completionStatus: statuses[(currentIndex + 1) % statuses.length] };
      }
      return i;
    }));
  };

  const handleGenerateAI = async () => {
    setIsGeneratingAI(true);
    const summary = await generateMarketSummary(insights);
    setAiSummary(summary || "分析完成。");
    setIsGeneratingAI(false);
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-red-100 selection:text-red-900 bg-white">
      <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-2xl border-b border-gray-100 px-8 py-5">
        <div className="max-w-[1600px] mx-auto grid grid-cols-[240px_1fr_240px] items-center">
          <div className="flex items-center gap-4">
            <div className="bg-gray-900 p-3 rounded-[1.25rem] shadow-xl shadow-gray-200 rotate-[-5deg]">
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-black text-gray-900 tracking-tight leading-none mb-1">市场周刊</h1>
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em]">Weekly Analysis</p>
            </div>
          </div>

          <div className="flex justify-center">
            <nav className="flex items-center bg-gray-100/50 p-1.5 rounded-2xl border border-gray-200/50 gap-1.5 shadow-inner">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-7 py-2.5 rounded-xl text-[14px] font-black transition-all whitespace-nowrap active:scale-90 relative ${
                    activeCategory === cat ? 'bg-white text-gray-900 shadow-xl shadow-gray-200/50 border border-gray-100' : 'text-gray-400 hover:text-gray-900 hover:bg-white/40'
                  }`}
                >
                  {cat}
                  {activeCategory === cat && <span className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-red-500 rounded-full"></span>}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-3 justify-end">
            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-red-500 text-white px-6 py-3 rounded-2xl hover:bg-red-600 transition-all flex items-center gap-2.5 shadow-2xl shadow-red-200 font-black text-sm active:scale-95 group"
            >
              <Plus className="w-4 h-4 transition-transform group-hover:rotate-90" />
              <span>新记录</span>
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-12">
        <aside className="lg:w-60 space-y-12 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2.5 mb-6 px-1">
              <Clock className="w-4 h-4 text-gray-400" />
              <h3 className="text-[12px] font-black text-gray-400 uppercase tracking-[0.2em]">时间轴归档</h3>
            </div>
            <div className="space-y-2">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-5 py-3.5 rounded-2xl text-[13px] font-black transition-all flex items-center justify-between group border-2 ${
                  selectedMonth === null ? 'bg-white border-gray-900 shadow-xl shadow-gray-100 text-gray-900' : 'bg-transparent border-transparent text-gray-400 hover:text-gray-900 hover:bg-gray-50 hover:border-gray-200'
                }`}
              >
                <span className="flex items-center gap-3">
                  <Hash className={`w-4 h-4 ${selectedMonth === null ? 'text-red-500' : 'text-gray-300'}`} />
                  全部时间
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded-lg font-black ${selectedMonth === null ? 'bg-red-50 text-red-500' : 'bg-gray-100/50 text-gray-400'}`}>
                  {insights.length}
                </span>
              </button>
              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-5 py-3.5 rounded-2xl text-[13px] font-black transition-all flex items-center justify-between group border-2 ${
                    selectedMonth === month ? 'bg-white border-gray-900 shadow-xl shadow-gray-100 text-gray-900' : 'bg-transparent border-transparent text-gray-400 hover:text-gray-900 hover:bg-gray-50 hover:border-gray-200'
                  }`}
                >
                  <span className="flex items-center gap-3">
                    <Calendar className={`w-4 h-4 ${selectedMonth === month ? 'text-red-500' : 'text-gray-300'}`} />
                    {month}
                  </span>
                  <span className={`text-[10px] px-2 py-0.5 rounded-lg font-black ${selectedMonth === month ? 'bg-red-50 text-red-500' : 'bg-gray-100/50 text-gray-400'}`}>
                    {count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <MarketDashboard 
            insights={insights} 
            onGenerateAI={handleGenerateAI} 
            isGeneratingAI={isGeneratingAI} 
            aiSummary={aiSummary} 
          />

          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-8 mb-14">
            <div className="space-y-2">
              <p className="text-[12px] font-black text-gray-900 uppercase tracking-[0.3em]">Market Insights</p>
              <h2 className="text-4xl font-black text-gray-900 tracking-tight italic">
                保持敏锐，记录每一份洞察。
              </h2>
            </div>

            <div className="flex bg-gray-50 p-1.5 rounded-2xl items-center border border-gray-200/50">
              <button onClick={() => setSortMode('category')} className={`px-5 py-2.5 rounded-xl text-[11px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-md border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                <ListFilter className="w-3.5 h-3.5 mr-2 inline" /> 按类别
              </button>
              <button onClick={() => setSortMode('timeline')} className={`px-5 py-2.5 rounded-xl text-[11px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-md border border-gray-100' : 'text-gray-400 hover:text-gray-600'}`}>
                <CalendarDays className="w-3.5 h-3.5 mr-2 inline" /> 时间线
              </button>
            </div>
          </div>

          {activeItems.length > 0 ? (
            <div className="space-y-20">
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel}>
                  <div className="flex items-center gap-5 mb-10 sticky top-[120px] z-10 py-4">
                    <div className="flex items-center gap-3 px-6 py-2.5 bg-white/90 backdrop-blur-md rounded-2xl border border-gray-200 shadow-xl shadow-gray-100/20">
                      <span className="text-[13px] font-black text-gray-900">{groupLabel}</span>
                    </div>
                    <div className="h-[2px] flex-grow bg-gradient-to-r from-gray-200/50 to-transparent"></div>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleStatus={handleToggleStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : (
            <div className="text-center py-40 bg-gray-50/50 rounded-[4rem] border border-dashed border-gray-200">
              <h3 className="text-2xl font-black text-gray-900 mb-3">当前没有活跃观点</h3>
              <p className="text-sm text-gray-400 mb-10">开始记录你对市场的新想法吧。</p>
            </div>
          )}

          {archivedItems.length > 0 && (
            <div className="mt-32 space-y-12">
               <div className="flex items-center gap-5 border-t border-gray-100 pt-20 mb-10">
                  <Archive className="w-6 h-6 text-gray-300" />
                  <h3 className="text-xl font-black text-gray-400">已归档历史 (已完成/失效)</h3>
               </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-10">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleStatus={handleToggleStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto border-t border-gray-100 py-16 bg-gray-50/30 text-center">
          <p className="text-[11px] text-gray-300 font-black uppercase tracking-[0.5em]">Trading Journal Pro · EST. 2025</p>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, CheckCircle2, Circle, AlertCircle, TrendingUp, TrendingDown, Activity, Target, Check, X } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'bg-white/80 text-red-600 border-red-200',
      accent: 'bg-red-50/50 border-red-500 text-red-900',
      icon: <TrendingUp className="w-3.5 h-3.5" />
    };
    case '看跌': return {
      color: 'bg-white/80 text-green-600 border-green-200',
      accent: 'bg-green-50/50 border-green-500 text-green-900',
      icon: <TrendingDown className="w-3.5 h-3.5" />
    };
    case '震荡': return {
      color: 'bg-white/80 text-blue-600 border-blue-200',
      accent: 'bg-blue-50/50 border-blue-500 text-blue-900',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    default: return {
      color: 'bg-white/80 text-gray-500 border-gray-200',
      accent: 'bg-gray-50/50 border-gray-400 text-gray-900',
      icon: <Circle className="w-3.5 h-3.5" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const completionStatus = insight.completionStatus;
  const { color, icon, accent } = getAssetStatusStyle(insight.status);

  const getCardStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-gray-50/50 border-emerald-100 shadow-sm opacity-90 grayscale-[0.3] hover:grayscale-0';
      case '已失效': return 'bg-slate-50/80 border-slate-200 shadow-none opacity-80 grayscale';
      default: return 'bg-white border-gray-200/80 shadow-sm hover:shadow-2xl hover:-translate-y-1';
    }
  };

  const getTagStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-emerald-500 text-white';
      case '已失效': return 'bg-slate-400 text-white';
      default: return 'bg-sky-500 text-white';
    }
  };

  const getStatusIcon = () => {
    switch (completionStatus) {
      case '已完成': return <CheckCircle2 className="w-3 h-3" />;
      case '已失效': return <AlertCircle className="w-3 h-3" />;
      default: return <Circle className="w-3 h-3" />;
    }
  };

  return (
    <div className={`group relative border rounded-[2rem] p-6 transition-all duration-500 flex flex-col h-full overflow-hidden ${getCardStyle()}`}>

      {/* 背景巨型 Logo */}
      {completionStatus === '已完成' && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.05] group-hover:opacity-[0.08] transition-opacity">
          <Check className="w-48 h-48 text-emerald-600" />
        </div>
      )}
      {completionStatus === '已失效' && (
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.05] group-hover:opacity-[0.08] transition-opacity">
          <X className="w-48 h-48 text-red-600" />
        </div>
      )}

      {/* 顶部状态标记 */}
      <div className="absolute -top-3 left-6 flex gap-2 z-10">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider shadow-lg transition-all active:scale-90 hover:brightness-110 cursor-pointer ${getTagStyle()}`}
        >
          {getStatusIcon()}
          {completionStatus}
        </button>
      </div>

      <div className="relative z-10 flex justify-between items-start mb-4 gap-3 pt-2">
        <div className="flex-grow">
          <h3 className="text-2xl font-black text-gray-900 tracking-tight mb-1">{insight.symbol}</h3>
          <div className="flex items-center text-[10px] text-gray-400 gap-1.5 font-bold">
            <Calendar className="w-3 h-3 opacity-60" />
            {date}
          </div>
        </div>
        <div className={`px-3 py-1.5 rounded-xl text-[11px] font-black border flex items-center justify-center gap-2 shrink-0 min-w-[80px] shadow-sm ${color}`}>
          {insight.status}
          {icon}
        </div>
      </div>

      <div className="relative z-10 space-y-4 flex-grow">
        <div className={`p-4 rounded-2xl border transition-colors ${completionStatus === '进行中' ? 'bg-gray-50/50 border-gray-100' : 'bg-white/40 border-transparent'}`}>
          <p className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-2">核心观察</p>
          <p className={`text-sm leading-relaxed font-medium line-clamp-4 text-gray-700`}>
            {insight.focusPoints}
          </p>
        </div>

        {insight.entryLevel && (
          <div className={`flex items-center justify-between p-3 px-4 rounded-2xl border border-dashed bg-gray-500/5 border-gray-200`}>
            <p className="text-[11px] font-black uppercase tracking-widest text-gray-500">入场点位</p>
            <div className="flex items-center gap-2">
              <Target className="w-3 h-3 text-gray-300" />
              <p className="text-lg font-black tracking-tighter text-gray-900">{insight.entryLevel}</p>
            </div>
          </div>
        )}

        <div className={`p-5 rounded-2xl border-l-[6px] transition-all ${completionStatus === '进行中' ? accent : 'bg-gray-200/20 border-gray-300 text-gray-500'}`}>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60 mb-2">交易策略</p>
          <p className={`text-[13px] font-bold leading-relaxed ${completionStatus === '进行中' ? 'text-gray-900' : 'text-gray-400'}`}>
            {insight.strategy}
          </p>
        </div>
      </div>

      <div className="relative z-10 mt-6 pt-5 border-t border-gray-100/60 flex justify-end items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-300">
        <button 
          onClick={() => onEdit(insight)}
          className="p-2.5 text-gray-400 hover:text-gray-900 hover:bg-white rounded-xl transition-colors flex items-center gap-2 text-[11px] font-black"
        >
          <Edit2 className="w-3.5 h-3.5" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="p-2.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-colors flex items-center gap-2 text-[11px] font-black"
        >
          <Trash2 className="w-3.5 h-3.5" />
          删除
        </button>
      </div>
    </div>
  );
};

export default MarketCard;
